let angle = 0;
let scale = 1;
let strokeSize = 2;

function setup() {
  createCanvas(600, 600, WEBGL);
}

function draw() {
  background(0);
  translate(width / 2, height / 2);
  rotateZ(angle);
  rotateX(angle);

  drawHeartFrac(0, 0, scale);

  angle += 0.01;
  scale += 0.001;
  strokeSize += 0.01;
}

function drawHeartFrac(x, y, sz) {
  push();
  translate(x, y);

  // Draw the heart shape
  beginShape();
  vertex(-sz, -sz);
  bezierVertex(-sz, sz, sz, sz, sz, -sz);
  bezierVertex(sz, -sz, -sz, -sz, -sz, -sz);
  endShape(CLOSE);

  // Fractal internal structure
  if (sz > 1) {
    for (let i = 0; i < 4; i++) {
      let x2 = x + sin(i * TWO_PI / 4) * sz;
      let y2 = y + cos(i * TWO_PI / 4) * sz;
      drawHeartFrac(x2, y2, sz * 0.7);
    }
  }

  pop();
}
```
