¡Excelente elección! Crear un juego de match-3 como Bejeweled en Unity con C# puede ser un proyecto divertido y desafiante. Empecemos por paso a paso.

**Paso 1: Crear un nuevo proyecto en Unity**

* Abre Unity y selecciona "New" en la pantalla de inicio.
* Selecciona "3D" como proyecto y da un nombre a tu juego (por ejemplo, "BejeweledCasual").
* Selecciona una ubicación para guardar tu proyecto y haz clic en "Create".

**Paso 2: Crear un juego en 2D**

* En la ventana de Unity, selecciona "GameObject" en el menú del Editor y haz clic en "Tilemap" (en la categoría "2D").
* Llame a tu tilemap "GameBoard".
* Arrastre y suelte la tilemap en la ventana de Unity.

**Paso 3: Agregar tiles y.swap animaciones**

* En la ventana de Unity, selecciona "GameObject" y luego "Tile" en el menú del Editor.
* Llame a tu tile "Tile".
* Agrega varios tiles a la tilemap (GameBoard) arrastrando y soltando en la ventana de Unity.
* Para agregar animaciones de swap, crea un nuevo sprite para la imagen de swap (por ejemplo, "SwapImage.png").
* Agrega el sprite de swap a una nueva capa en la tilemap (GameBoard).
* En el Inspector, selecciona la capa con el sprite de swap y establece su "Sorting Layer" en "Swaplayer".

**Paso 4: Crear el script para el juego**

* En la ventana de Unity, selecciona "Assets" en el menú del Editor y luego "Create" > "C# Script".
* Llame a tu script "GameController.cs".
* Agrega el script a la tilemap (GameBoard) arrastrando y soltando en la ventana de Unity.

**Paso 5: Agregar lógica al script**

* En el script "GameController.cs", agrega las siguientes líneas de código:
```csharp
using UnityEngine;

public class GameController : MonoBehaviour
{
    // Tiles en la tilemap
    public GameObject[] tiles;

    // Sprite de swap
    public Sprite swapImage;

    // Tipo de juego (match-3)
    public int rows = 8;
    public int cols = 8;
    public int numTiles = 64;

    // Estado del juego (iniciado, pausado, terminado)
    public enum GameStatus { Init, Paused, Ended }
    public GameStatus gameStatus = GameStatus.Init;

    void Start()
    {
        // Inicializa la tilemap
        InitializeTilemap();
    }

    void InitializeTilemap()
    {
        // Asigna tiles al array
        tiles = new GameObject[numTiles];
        for (int i = 0; i < numTiles; i++)
        {
            GameObject tile = Instantiate(tiles[0], new Vector3(i % cols, i / cols, 0), Quaternion.identity);
            tiles[i] = tile;
        }
    }

    void Update()
    {
        // Registra eventos de click en la tilemap
        if (Input.GetMouseButtonDown(0))
        {
            // Obtiene la posición del click
            Vector2 pos = GetMousePosition();
            // Verifica si el click está dentro de la tilemap
            if (pos.x >= 0 && pos.x < cols && pos.y >= 0 && pos.y < rows)
            {
                // Seleciona la tile en la posición del click
                GameObject selectedTile = tiles[(int)pos.x + (int)pos.y * cols];
                // Verifica si la tile es seleccionable
                if (selectedTile.GetComponent<Tile>().isSelectible)
                {
                    // Realiza el match-3
                    PerformMatch3(selectedTile);
                }
            }
        }
    }

    void PerformMatch3(GameObject selectedTile)
    {
        // Obtiene la posición actual de la tile seleccionada
        int selectedTileX = (int)selectedTile.transform.position.x;
        int selectedTileY = (int)selectedTile.transform.position.y;

        // Busca tiles adyacentes que sean iguales a la tile seleccionada
        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                int tileX = selectedTileX + dx;
                int tileY = selectedTileY + dy;
                if (tileX >= 0 && tileX < cols && tileY >= 0 && tileY < rows)
                {
                    GameObject adjacentTile = tiles[tileX + (int)tileY * cols];
                    if (adjacentTile.GetComponent<Tile>().type == selectedTile.GetComponent<Tile>().type)
                    {
                        // Swaps tiles
                        SwapTiles(selectedTile, adjacentTile);
                    }
                }
            }
        }
    }

    void SwapTiles(GameObject tile1, GameObject tile2)
    {
        // Obtiene la posición actual de las tiles
        int tile1X = (int)tile1.transform.position.x;
        int tile1Y = (int)tile1.transform.position.y;
        int tile2X = (int)tile2.transform.position.x;
        int tile2Y = (int)tile2.transform.position.y;

        // Realiza el swap
        GameObject temp = tile1;
        tile1 = tile2;
        tile2 = temp;

        // Position the tile in the new position
        tile1.transform.position = new Vector3(tile1X, tile1Y, 0);
        tile2.transform.position = new Vector3(tile2X, tile2Y, 0);

        // Animate the swap with the sprite of swap
        StartCoroutine(AnimateSwap(tile1, tile2));
    }

    IEnumerator AnimateSwap(GameObject tile1, GameObject tile2)
    {
        // Animate the swap
        float duration = 0.5f;
        float timeElapsed = 0;
        while (timeElapsed < duration)
        {
            timeElapsed += Time.deltaTime;
            tile1.transform.position = Vector3.Lerp(tile1.transform.position, tile2.transform.position, timeElapsed / duration);
            tile2.transform.position = Vector3.Lerp(tile2.transform.position, tile1.transform.position, timeElapsed / duration);
            yield return null;
        }
    }

    // Get the mouse position
    Vector2 GetMousePosition()
    {
        return Camera.main.ScreenToWorldPoint(Input.mousePosition);
    }
}
```
