import React, { useState } from 'react';

const Modal = ({ children, isOpen, onClose }) => {
  const [show, setShow] = useState(isOpen);

  const handleClose = () => {
    setShow(false);
    onClose();
  };

  if (!show) {
    return null;
  }

  return (
