Here is a basic implementation of an autocomplete component in React, without relying on third-party packages:
```
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestionsList, setSuggestionsList] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (inputValue === '') {
        setSuggestionsList([]);
      } else {
        const filteredSuggestions = suggestions.filter((suggestion) => {
          return suggestion.toLowerCase().includes(inputValue.toLowerCase());
        });
        setSuggestionsList(filteredSuggestions);
      }
    }, 300);
    return () => {
      clearTimeout(timer);
    };
  }, [inputValue]);

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSuggestionSelect = (suggestion) => {
    onSelect(suggestion);
    setInputValue('');
  };

  const handleArrowKeyNavigation = (event) => {
    if (event.key === 'ArrowDown') {
      setActiveSuggestionIndex(Math.min(activeSuggestionIndex + 1, suggestionsList.length - 1));
    } else if (event.key === 'ArrowUp') {
      setActiveSuggestionIndex(Math.max(activeSuggestionIndex - 1, 0));
    }
  };

  const handleEnterKey = (event) => {
    if (event.key === 'Enter') {
      handleSuggestionSelect(suggestionsList[activeSuggestionIndex]);
    }
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyPress={handleEnterKey}
      />
      {suggestionsList.map((suggestion, index) => {
        const isSuggestionSelected = index === activeSuggestionIndex;
        return (
          <div
            key={suggestion}
            className={`suggestion ${isSuggestionSelected ? 'selected' : ''}`}
            onClick={() => handleSuggestionSelect(suggestion)}
          >
            {suggestion}
          </div>
        );
      })}
    </div>
  );
};

export default Autocomplete;
```
