using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;

namespace MyHttpServer
{
    class Program
    {
        static void Main(string[] args)
        {
            // Créer un nouveau HttpListener
            HttpListener listener = new HttpListener();
            listener.Prefixes.Add("http://localhost:8080/hello");

            // Démarrer le serveur
            listener.Start();

            Console.WriteLine("Serveur démarré. Appuyez sur Entrée pour stopper.");

            // Attendre des requêtes
            while (true)
            {
                HttpListenerContext context = listener.GetContext();

                // Traitement de la requête GET
                HttpListenerRequest request = context.Request;
                if (request.HttpMethod == "GET")
                {
                    // Répondre avec un message "Hello"
                    string response = "Hello";
                    context.Response.StatusCode = 200;
                    context.Response.ContentType = "text/plain";
                    byte[] buffer = Encoding.UTF8.GetBytes(response);
                    context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                    context.Response.OutputStream.Close();
                }
                else
                {
                    // Erreur 404 si la méthode n'est pas GET
                    context.Response.StatusCode = 404;
                }
            }
        }
    }
}
```
