const double alpha = 0.1; // параметр
const double gamma = 0.022; // параметр
const double mu = 0.01; // параметр
const double zeta = 1.0; // граница по ζ

// функция M
double M(double h, double alpha) {
  return pow(h + alpha, 4) / (16 * mu * (3 * pow(1 + h / alpha, 4) - 4 * pow(1 + h / alpha, 2) + 1 - 4 * pow(1 + h / alpha, 4) * log(1 + h / alpha)));
}

// функция p
double p(double h, double dh, double d2h) {
  return -gamma * (d2h / (1 + pow(dh, 2))^(3/2) - (1 - alpha * dh) / ((alpha * h) * (1 + pow(dh, 2))^(1/2)));
}

int main() {
  // инициализация массивов
  int N = 100; // количество точек по ζ
  double h[N]; // массив для хранения функции h
  double p[N]; // массив для хранения функции p
  double dh[N]; // массив для хранения производной h по ζ
  double d2h[N]; // массив для хранения второй производной h по ζ

