  h[0] = 5e-7; // h(0,t)=50*10^(-6)
  p[0] = 1100; // p(0,t)=0.022/(20*10^(-6))
  dh[0] = 0; // производная h по ζ в точке ζ=0
  d2h[0] = 0; // вторая производная h по ζ в точке ζ=0

