  double t = 0.0;

  // время
  double dt = 1e-6; // время шага
  int iter = 0; // количество шагов

  // итерации по времени
  while (t < 1.0) {
    // итерации по space
    for (int i = 1; i < N; i++) {
      // баундиный условие
      if (i == N - 1) {
        dh[i] = 0;
        d2h[i] = 0;
      } else {
        // численное differentiation
        dh[i] = (h[i + 1] - h[i]) / zeta;
        d2h[i] = (dh[i + 1] - dh[i]) / zeta;
      }

      // численное решение
      double res = 1 / (zeta * alpha + h[i]) * (Mvals[i] * d2h[i] - dh[i]);
